/// Replaces r'${i}' in every string (repeat steps, $each matchers).
Object? substitute(Object? v, int i) {
  if (v is String) return v.replaceAll(r'${i}', '$i');
  if (v is List) return v.map((e) => substitute(e, i)).toList();
  if (v is Map) {
    return v.map((k, e) => MapEntry(substitute(k, i), substitute(e, i)));
  }
  return v;
}

/// The value an app passes for fixture input: $number, $repeat, $keys, $list decoded.
Object? decodeInput(Object? v) {
  if (v is List) return v.map(decodeInput).toList();
  if (v is Map) {
    if (v.length == 1) {
      final g = v.values.first;
      switch (v.keys.first) {
        case r'$number':
          return g == 'NaN'
              ? double.nan
              : (g == 'Infinity' ? double.infinity : double.negativeInfinity);
        case r'$repeat':
          return (g['string'] as String) * (g['count'] as int);
        case r'$keys':
          return {
            for (var i = 0; i < (g['count'] as int); i++)
              '${g['prefix']}$i': decodeInput(g['value'])
          };
        case r'$list':
          return List.generate(
              g['count'] as int, (_) => decodeInput(g['value']));
      }
    }
    return v.map((k, e) => MapEntry(k as String, decodeInput(e)));
  }
  return v;
}
